package dev.chyken.assembl_ar.workflow.phase;
import org.junit.Test;import static org.junit.Assert.*;import static dev.chyken.assembl_ar.workflow.phase.Phase11OledBatteryFlow.Screen.*;
public final class Phase11OledBatteryFlowTest {
    @Test public void fullRouteRequiresEveryScanExplicitDemoAndPhysicalCheck(){Phase11OledBatteryFlow f=new Phase11OledBatteryFlow(0);for(int i=1;i<=8;i++){
        assertEquals(i,f.step());assertFalse(f.next(i));if(f.screen().scan()){f.confirm();assertFalse(f.complete());f.observe(true);assertFalse(f.complete());f.observe(true);}else if(f.screen().check()){f.answerSecure(false);assertFalse(f.complete());f.answerSecure(true);}else {assertFalse(f.scanning());f.confirm();}assertTrue(f.complete());assertTrue(f.next(i));
    }assertEquals(CELEBRATION,f.screen());assertTrue(f.allComplete());assertTrue(f.canFinish(false));assertFalse(f.next(20));}
    @Test public void oldOrRepeatedFramesAndPauseCannotFinishAScan(){Phase11OledBatteryFlow f=new Phase11OledBatteryFlow(10);Object old=f.tag();assertFalse(f.accepts(old,9));assertTrue(f.accepts(old,11));assertFalse(f.accepts(old,11));f.observe(true);f.pause();assertFalse(f.accepts(old,12));f.resume(20);assertFalse(f.accepts(old,21));assertFalse(f.accepts(f.tag(),19));f.observe(true);assertFalse(f.complete());}
    @Test public void reviewingDemoPreservesChecksAndRescanInvalidatesOnlyDependentCheck(){Phase11OledBatteryFlow f=new Phase11OledBatteryFlow(0);f.devComplete();f.devJump(5,1);f.rescan(2);assertFalse(f.complete());f.devJump(6,3);assertFalse(f.complete());f.previous(4);f.previous(5);assertEquals(OLED_DEMO,f.screen());assertTrue(f.complete());assertFalse(f.scanning());f.next(6);assertFalse(f.complete());}
    @Test public void checkpointRestoresExactScreenAndLegacyBatteryKeepsOledEvidence(){Phase11OledBatteryFlow f=new Phase11OledBatteryFlow(0);f.devComplete();f.devJump(7,1);Phase11OledBatteryFlow saved=Phase11OledBatteryFlow.restore(f.snapshot(),20);assertEquals(BATTERY_DEMO,saved.screen());assertTrue(saved.complete());assertFalse(saved.scanning());Phase11OledBatteryFlow old=Phase11OledBatteryFlow.restore("legacyBattery",30);assertEquals(BATTERY_SCAN,old.screen());assertTrue(old.scanning());assertFalse(old.inventoryComplete());assertFalse(old.canFinish(false));old.devJump(6,40);assertTrue(old.complete());}
    @Test public void developerJumpCannotCertifyLearnerAndMalformedStateCannotFinish(){Phase11OledBatteryFlow f=new Phase11OledBatteryFlow(0);f.devJump(9,1);assertFalse(f.canFinish(false));assertTrue(f.canFinish(true));for(String bad:new String[]{null,"garbage","1:9,111","1:99,111111111"})assertFalse(Phase11OledBatteryFlow.restore(bad,0).allComplete());}
    @Test public void finalPhaseSavesBothOldSectionsAndOldBatterySessionMigrates(){AssemblyPhase p=AssemblyPhaseCatalog.byId(AssemblyPhaseCatalog.OLED_FIT);assertSame(p,AssemblyPhaseCatalog.byId(AssemblyPhaseCatalog.BATTERY_FIT));assertEquals(java.util.Arrays.asList(17,18),PhaseProgress.sectionsToSave(p,17));assertEquals(java.util.Arrays.asList(18),PhaseProgress.sectionsToSave(p,18));PhaseSessionCheckpoint old=new PhaseSessionCheckpoint(AssemblyPhaseCatalog.BATTERY_FIT,false,PhaseFlow.Mode.DEMO,0,0,true,false,null);assertEquals(p.getId(),old.phaseId);assertEquals("legacyBattery",old.gearState);assertEquals(9,PhaseGuideMetadata.subSteps(p).size());}
    @Test public void sharedRootUsesFinalFlowForEvidenceAndPause(){PhaseFlow root=new PhaseFlow(AssemblyPhaseCatalog.byId(AssemblyPhaseCatalog.OLED_FIT),0,false);Phase11OledBatteryFlow f=new Phase11OledBatteryFlow(0);root.attachOledBatteryFlow(f);assertEquals(f.tag(),root.tag());assertTrue(root.collectsEvidence());root.interrupt(2);assertFalse(root.collectsEvidence());root.resume(3);assertTrue(root.collectsEvidence());f.devJump(4,4);assertFalse(root.collectsEvidence());assertFalse(root.canScan());}
}
